{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Membership pricing and packages for coaching that builds reliable habits and clear frameworks.">
  <style>
    :root{--bg:#f7faf7;--card:#ffffff;--muted:#6b7280;--accent:#2f855a;--accent-2:#234e52;--glass:rgba(255,255,255,0.6);--shadow:0 6px 18px rgba(15,23,42,0.08)}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.5;color:#0f172a;background:var(--bg) url("assets/img/pattern.svg") repeat;}
    header{background:linear-gradient(180deg,rgba(255,255,255,0.8),rgba(255,255,255,0.6));backdrop-filter:blur(6px);border-bottom:1px solid rgba(15,23,42,0.04)}
    .wrap{max-width:1000px;margin:0 auto;padding:18px}
    nav{display:flex;align-items:center;gap:18px}
    .logo{font-weight:700;color:var(--accent-2)}
    .nav-links{margin-left:auto;display:flex;gap:14px}
    .nav-links a{color:var(--muted);text-decoration:none;font-weight:600;padding:8px 10px;border-radius:8px}
    .nav-links a.active, .nav-links a:hover{background:var(--glass);color:var(--accent-2)}

    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:36px 18px}
    .hero h1{margin:0;font-size:26px;color:var(--accent-2)}
    .hero p.lead{margin:6px 0 0;color:var(--muted)}
    .cta-row{display:flex;gap:12px;margin-top:14px}
    .btn{display:inline-flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;border:0;background:var(--accent);color:#fff;font-weight:700;text-decoration:none}
    .btn.ghost{background:transparent;color:var(--accent-2);border:1px solid rgba(15,23,42,0.06)}

    .pricing-wrap{display:grid;grid-template-columns:1fr;gap:18px;padding:18px}
    .panel{background:var(--card);border-radius:12px;padding:18px;box-shadow:var(--shadow)}

    .toggle{display:flex;align-items:center;gap:10px}
    .switch{background:#e6f7ef;border-radius:999px;padding:6px;display:inline-flex;width:120px;position:relative}
    .toggle-option{flex:1;text-align:center;font-weight:700;color:var(--muted);cursor:pointer}
    .knob{width:56px;height:32px;background:var(--accent);border-radius:999px;position:absolute;top:4px;left:4px;transition:left .34s cubic-bezier(.2,.9,.2,1)}

    .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .tier{padding:16px;border-radius:10px;border:1px solid rgba(15,23,42,0.04);background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff)}
    .tier h3{margin:0 0 6px;color:var(--accent-2)}
    .price{font-size:22px;font-weight:800;color:var(--accent);display:flex;align-items:baseline;gap:8px}
    .per{font-size:13px;color:var(--muted);font-weight:600}
    .features{margin:12px 0 0;color:var(--muted);font-size:14px}
    .highlight{background:linear-gradient(90deg,rgba(47,133,90,0.08),rgba(35,78,82,0.04));padding:10px;border-radius:8px;margin-top:12px;color:var(--accent-2)}

    .savings{margin-top:12px;font-weight:700;color:#047857}

    footer{padding:24px;text-align:center;color:var(--muted)}

    @media(max-width:860px){.tiers{grid-template-columns:1fr}.wrap{padding:12px}.hero{padding:18px}}
  </style>
</head>
<body>
  <header>
    <div class="wrap" style="display:flex;align-items:center;">
      <div class="logo">{{BUSINESS_NAME}}</div>
      <nav class="nav-links" aria-label="Primary navigation">
        <a href="index.html">Overview</a>
        <a href="about.html">Approach</a>
        <a href="services.html">Sessions</a>
        <a href="programs.html">Journeys</a>
        <a href="pricing.html" class="active">Investment</a>
        <a href="testimonials.html">Proof</a>
        <a href="book.html">Begin</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero panel">
      <div>
        <h1>Membership plans that build steady habits and clear routines</h1>
        <p class="lead">Join a practical membership for predictable progress: weekly frameworks, habit checks, and a coach who helps translate intention into repeatable systems.</p>
        <div class="cta-row">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="book.html">Schedule a quick intro</a>
        </div>
      </div>
    </section>

    <section class="pricing-wrap">
      <div class="panel">
        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">
          <div>
            <strong>Choose billing</strong>
            <p style="margin:6px 0 0;color:var(--muted)">Toggle to compare monthly membership versus pre-paid package options.</p>
          </div>
          <div class="toggle" aria-hidden="false">
            <div class="switch" role="tablist" aria-label="Billing toggle" id="billingSwitch">
              <div class="knob" id="knob"></div>
              <div class="toggle-option" data-value="monthly">Monthly</div>
              <div class="toggle-option" data-value="package">Package</div>
            </div>
          </div>
        </div>

        <div class="tiers" id="tiers">
          <div class="tier">
            <h3>Essential</h3>
            <div class="price"><span class="amount" data-monthly="79" data-package="210">$79</span><span class="per">/mo</span></div>
            <div class="features">Weekly check-ins • Habit tracker • Email support</div>
            <div class="highlight">Good for building a consistent baseline.</div>
            <div class="savings" data-savings-monthly="0" data-savings-package="10">Save 10% when paid upfront</div>
          </div>

          <div class="tier">
            <h3>Growth</h3>
            <div class="price"><span class="amount" data-monthly="149" data-package="400">$149</span><span class="per">/mo</span></div>
            <div class="features">Weekly coaching calls • Custom frameworks • Priority messaging</div>
            <div class="highlight">Most members choose this for structured progress.</div>
            <div class="savings" data-savings-monthly="0" data-savings-package="12">Save 12% when pre-paid</div>
          </div>

          <div class="tier">
            <h3>Steward</h3>
            <div class="price"><span class="amount" data-monthly="249" data-package="660">$249</span><span class="per">/mo</span></div>
            <div class="features">Bi-weekly deep sessions • Personalized frameworks • Quarterly review</div>
            <div class="highlight">For sustained re-patterning and leadership of personal habits.</div>
            <div class="savings" data-savings-monthly="0" data-savings-package="15">Save 15% when paid upfront</div>
          </div>
        </div>
      </div>

      <div class="panel" style="display:flex;flex-direction:column;gap:12px">
        <strong>Compare total yearly commitment</strong>
        <p style="margin:0;color:var(--muted)">Switch to "Package" to see the cost for a three-month commitment paid at once and the instant savings.</p>
        <div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:12px">
          <div style="flex:1;padding:12px;border-radius:10px;background:linear-gradient(90deg,rgba(47,133,90,0.04),transparent);">Projected 12‑month spend: <div style="font-weight:800;color:var(--accent);font-size:18px" id="annualSum">$0</div></div>
          <div style="flex:1;padding:12px;border-radius:10px;background:#fff;border:1px solid rgba(15,23,42,0.03);">Typical onboarding session included for all members.</div>
        </div>
        <div style="margin-top:auto;display:flex;gap:10px;align-items:center">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">Join the membership</a>
          <a class="btn ghost" href="book.html">Book a planning call</a>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <div>{{BUSINESS_NAME}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="font-size:13px;margin-top:8px;color:var(--muted)">Memberships centered on outcomes, habits, and repeatable frameworks. No medical advice.</div>
  </footer>

  <script>
    (function(){
      const switchEl = document.getElementById('billingSwitch');
      const knob = document.getElementById('knob');
      let mode = 'monthly';
      const monthlyPos = 4;
      const packagePos = 60;
      function setMode(m,animate=true){
        mode = m;
        knob.style.left = (m==='monthly'? monthlyPos: packagePos) + 'px';
        document.querySelectorAll('.amount').forEach(el=>{
          const target = Number(el.dataset[m==='monthly'? 'monthly':'package']);
          animateNumber(el, target, m);
        });
        // calculate a simple annual sum: use monthly*12 for monthly, package*4 for 3-month packs across year
        const first = document.querySelector('.tiers .tier .amount');
        let sum=0;
        document.querySelectorAll('.tiers .tier .amount').forEach(el=>{
          const n = Number(el.dataset[m==='monthly'? 'monthly':'package']);
          if(m==='monthly') sum += n*12; else sum += n*4; // 3-month package counted 4 times
        });
        animatePlain(document.getElementById('annualSum'), sum);
      }

      function animateNumber(el, target, mode){
        const start = Number(el.textContent.replace(/[^0-9.]/g,'')) || 0;
        const duration = 520;
        const startTime = performance.now();
        const prefix = '$';
        (function tick(now){
          const t = Math.min(1,(now-startTime)/duration);
          const ease = 1 - Math.pow(1 - t, 3);
          const val = Math.round(start + (target - start)*ease);
          el.textContent = prefix + val;
          const per = el.parentElement.querySelector('.per');
          if(per) per.textContent = mode==='monthly'?'/mo':'/pack';
          if(t<1) requestAnimationFrame(tick);
        })(startTime);
      }

      function animatePlain(el, target){
        const start = Number(el.textContent.replace(/[^0-9.]/g,'')) || 0;
        const duration = 700; const startTime = performance.now();
        (function tick(now){
          const t = Math.min(1,(now-startTime)/duration);
          const ease = 1 - Math.pow(1 - t, 3);
          const val = Math.round(start + (target - start)*ease);
          el.textContent = '$' + val.toLocaleString();
          if(t<1) requestAnimationFrame(tick);
        })(startTime);
      }

      // attach events
      switchEl.querySelectorAll('.toggle-option').forEach(opt=>{
        opt.addEventListener('click',()=>{
          setMode(opt.dataset.value);
        });
      });

      // init
      setMode('monthly');
    })();
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Proof & Stories — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Rotating testimonials and credibility badges showcasing client experience and community impact.">
  <style>
    :root{--bg:#fcfdfc;--card:#fff;--muted:#6b7280;--accent:#1e6b59;--accent-2:#134e4a}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:var(--bg) url('assets/img/pattern.svg') repeat;color:#0f172a}
    .wrap{max-width:980px;margin:0 auto;padding:18px}
    header{display:flex;align-items:center;gap:14px;padding:12px 0}
    .logo{font-weight:700;color:var(--accent-2)}
    .nav{margin-left:auto;display:flex;gap:10px}
    .nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}

    .panel{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(15,23,42,0.06)}
    .hero{display:flex;gap:18px;align-items:center}
    .hero h1{margin:0;color:var(--accent-2)}
    .hero p{margin:6px 0 0;color:var(--muted)}

    .proof-gallery{display:grid;grid-template-columns:1fr 300px;gap:18px;margin-top:18px}
    .testimonial{padding:18px;border-radius:10px;background:linear-gradient(180deg,#fff,rgba(242,253,250,0.8));min-height:160px;position:relative}
    .quote{font-size:16px;margin:0 0 12px;color:#042b2a}
    .meta{font-weight:700;color:var(--accent-2)}
    .controls{display:flex;gap:8px;margin-top:12px}
    .dot{width:10px;height:10px;border-radius:50%;background:rgba(15,23,42,0.08);cursor:pointer}
    .dot.active{background:var(--accent)}

    .badges{display:flex;flex-direction:column;gap:10px}
    .badge{display:flex;align-items:center;gap:10px;background:#fff;padding:10px;border-radius:10px;border:1px solid rgba(15,23,42,0.04);cursor:default}
    .badge svg{width:28px;height:28px}
    .badge .label{font-weight:700;color:var(--accent-2)}
    .tooltip{font-size:13px;color:var(--muted);display:block}

    .cta-row{margin-top:18px;display:flex;gap:10px}
    .btn{padding:10px 14px;border-radius:10px;border:0;background:var(--accent);color:#fff;font-weight:700;text-decoration:none}
    .btn.ghost{background:transparent;border:1px solid rgba(15,23,42,0.06);color:var(--accent-2)}

    @media(max-width:920px){.proof-gallery{grid-template-columns:1fr}.badges{flex-direction:row;flex-wrap:wrap}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="logo">{{BUSINESS_NAME}}</div>
      <nav class="nav" aria-label="Primary navigation">
        <a href="index.html">Overview</a>
        <a href="about.html">Approach</a>
        <a href="programs.html">Journeys</a>
        <a href="services.html">Sessions</a>
        <a href="testimonials.html" style="font-weight:800;color:var(--accent-2)">Proof</a>
        <a href="pricing.html">Investment</a>
        <a href="book.html">Begin</a>
      </nav>
    </header>

    <main>
      <section class="panel hero">
        <div>
          <h1>Real progress. Short, honest reflections.</h1>
          <p>Stories from members about what changed when routines were supported by clear frameworks and consistent coaching.</p>
        </div>
      </section>

      <section class="proof-gallery" aria-live="polite">
        <div>
          <div class="panel testimonial" id="testimonial">
            <p class="quote" id="quote">"I shifted small daily habits that stacked into steady energy across my weeks. The coach helped me design prompts that stuck."</p>
            <div class="meta" id="meta">— Morgan, {{CITY}}</div>
            <div class="controls" id="controls"></div>
            <div style="margin-top:12px;color:var(--muted);font-size:14px">Memberships focus on habits, outcomes, and frameworks rather than one-off fixes.</div>
          </div>

          <div style="display:flex;gap:12px;margin-top:12px">
            <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="book.html">Book a discovery</a>
          </div>
        </div>

        <aside class="badges">
          <div class="panel" style="padding:12px;border-radius:10px">
            <div style="font-weight:800;color:var(--accent-2)">Proof & Credibility</div>
            <div style="margin-top:10px;display:flex;flex-direction:column;gap:8px">
              <div class="badge" data-tip="Featured pieces on habit design and sustainable routines">
                <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="12" r="10" stroke="#1e6b59" stroke-width="1.5"/></svg>
                <div>
                  <div class="label">Featured Contributor</div>
                  <span class="tooltip">Click for more</span>
                </div>
              </div>

              <div class="badge" data-tip="Led multi-week workshops for corporate and community groups">
                <svg viewBox="0 0 24 24" fill="none"><rect x="3" y="4" width="18" height="14" rx="2" stroke="#1e6b59" stroke-width="1.5"/></svg>
                <div>
                  <div class="label">Workshop Host</div>
                  <span class="tooltip">Hover to read details</span>
                </div>
              </div>

              <div class="badge" data-tip="Facilitated 20+ small cohorts focused on daily routines and workplace wellness">
                <svg viewBox="0 0 24 24" fill="none"><path d="M12 3v18M3 12h18" stroke="#1e6b59" stroke-width="1.5"/></svg>
                <div>
                  <div class="label">Cohort Leader</div>
                  <span class="tooltip">Learn about cohorts</span>
                </div>
              </div>
            </div>
          </div>

          <div class="panel" style="padding:12px;border-radius:10px">
            <div style="font-weight:700;color:var(--accent-2)">Community notes</div>
            <div style="margin-top:8px;color:var(--muted);font-size:14px">Clients report better follow-through on habits and clarity in priorities. These highlights represent personal experience, not medical claims.</div>
          </div>
        </aside>
      </section>
    </main>

    <footer style="padding-top:18px;text-align:center;color:var(--muted)">
      <div>{{BUSINESS_NAME}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
    </footer>
  </div>

  <script>
    (function(){
      const testimonials = [
        {quote: 'I shifted small habits that stacked into steady energy across my weeks. The coach helped me design prompts that stuck.', meta: 'Morgan, {{CITY}}'},
        {quote: 'The frameworks helped me decide what mattered each week so I did not waste time on vague goals.', meta: 'Riley, {{CITY}}'},
        {quote: 'Weekly check-ins kept me honest. Four months later I had a repeatable rhythm that actually lasted.', meta: 'Sam, {{CITY}}'},
        {quote: 'The membership structure made it simple to keep momentum — consistent practice with measured adjustments.', meta: 'Taylor, {{CITY}}'}
      ];

      let index = 0;
      const quoteEl = document.getElementById('quote');
      const metaEl = document.getElementById('meta');
      const controls = document.getElementById('controls');

      function renderControls(){
        controls.innerHTML = '';
        testimonials.forEach((t,i)=>{
          const dot = document.createElement('div');
          dot.className = 'dot' + (i===index? ' active':'');
          dot.addEventListener('click', ()=>{ setIndex(i); });
          controls.appendChild(dot);
        });
      }

      function setIndex(i){
        index = i; update();
      }

      function update(){
        // subtle fade
        quoteEl.style.opacity = 0; metaEl.style.opacity=0;
        setTimeout(()=>{
          quoteEl.textContent = '"' + testimonials[index].quote + '"';
          metaEl.textContent = '— ' + testimonials[index].meta;
          quoteEl.style.opacity=1; metaEl.style.opacity=1;
        },220);
        renderControls();
      }

      function next(){ index = (index+1)%testimonials.length; update(); }

      // auto rotate
      let timer = setInterval(next, 6000);
      // pause on hover
      document.getElementById('testimonial').addEventListener('mouseenter', ()=>clearInterval(timer));
      document.getElementById('testimonial').addEventListener('mouseleave', ()=>{ timer = setInterval(next,6000); });

      // badges tooltips
      document.querySelectorAll('.badge').forEach(b=>{
        const tip = b.getAttribute('data-tip');
        b.addEventListener('mouseenter', ()=>{
          const t = document.createElement('div');
          t.className='tip'; t.textContent=tip;
          t.style.position='absolute'; t.style.background='#fff'; t.style.border='1px solid rgba(15,23,42,0.06)'; t.style.padding='8px'; t.style.borderRadius='8px'; t.style.boxShadow='0 8px 20px rgba(2,6,23,0.08)'; t.style.zIndex=1000;
          b._tipEl = t; document.body.appendChild(t);
          const r = b.getBoundingClientRect();
          t.style.left = (r.right + 10) + 'px'; t.style.top = (r.top) + 'px';
        });
        b.addEventListener('mouseleave', ()=>{ if(b._tipEl){ document.body.removeChild(b._tipEl); b._tipEl=null; } });
      });

      renderControls(); update();
    })();
  </script>
</body>
</html>"} 
